import { HttpErrorResponse } from '@angular/common/http';
import { FigurePipe } from '../../core/locale';
import { Component, inject, input, output, signal } from '@angular/core';
import { FISCAL_YEAR, PERIOD_CAP, PERIOD_DATE, PeriodView, PeriodsApi, fiscalYearOf } from '../../core/periods';
import { Session } from '../../core/session';

// The sheet's periods: listed by from-date with the due-total of the counting claims dated in each,
// and one form to add a period (a unique name and inclusive from and to dates, overlapping no other).
// Its due-total is the sum of the people's figures for it. A period can be closed: each person's figure
// is then the one fixed at closing. It can instead be soft-closed: the figures are fixed the same way
// but its claims can still change; a soft-closed period can then be closed or reopened. A permitted role (a steward by default) can reopen a
// closed period, making its due-total live again. A second form generates a period per calendar month
// over a range of dates, named yyyy-mm, leaving out months whose name is taken or that overlap a period;
// a third does the same for the twelve months of a fiscal year. Each period shows the fiscal year its
// from-date falls in. A period may cap the OPEN or PENDING claims due by in it each person may have.
// A steward can lock a period, so it cannot be reopened, and unlock it again.
@Component({
  selector: 'app-periods',
  imports: [FigurePipe],
  template: `
      </form>
      <form (submit)="generateFiscalYear($event)" aria-label="Generate a fiscal year's monthly periods">
        <label for="period-generate-fy-year">Fiscal year (the calendar year it starts in, yyyy)</label>
        <input
          id="period-generate-fy-year"
          data-testid="period-generate-fy-year"
          inputmode="numeric"
          [value]="fiscalYear()"
          (input)="fiscalYear.set(value($event)); generateReset()"
        />
        <button type="submit" data-testid="period-generate-fy">Generate fiscal year</button>
      </form>
      <table>
        <thead>
          <tr>
            <th scope="col">Period</th>
            <th scope="col">From</th>
    }
  }

  /** Generate the fiscal year's monthly periods; how many were made is shown, a refusal as an error. */
  protected async generateFiscalYear(event: Event): Promise<void> {
    event.preventDefault();
    if (this.busy) return;
    this.generateReset();
    const sheet = this.session.sheet();
    if (!sheet) return;
    const year = this.fiscalYear().trim();
    if (!FISCAL_YEAR.test(year)) {
      this.generateError.set('Type the fiscal year as the four-digit calendar year it starts in.');
      return;
    }
    this.busy = true;
    try {
      const made = await this.api.generateFiscalYear(sheet, year);
      made.forEach((period) => this.saved.emit(period));
      this.generated.set(made.length);
    } catch {
      this.generateError.set('The fiscal year\'s periods could not be generated.');
    } finally {
      this.busy = false;
    }
  }

  protected async save(event: Event): Promise<void> {
export const PERIOD_DATE = /^\d{4}-\d{2}-\d{2}$/;

/** The period whose dates (inclusive) contain a date (yyyy-mm-dd), or null when none does. */
export function periodOn(periods: PeriodView[], date: string): PeriodView | null {
  return periods.find((p) => p.from <= date && date <= p.to) ?? null;
}

/** A fiscal year as the generate form takes it: the calendar year its first day falls in, four digits. */
export const FISCAL_YEAR = /^\d{4}$/;

/**
 * The name of the fiscal year a date (yyyy-mm-dd) falls in, FY<yyyy> by the calendar year its first
 * day falls in, for a fiscal year starting on the first of a month (1 to 12).
 */
export function fiscalYearOf(date: string, startMonth: number): string {
  const year = Number(date.slice(0, 4));
  const month = Number(date.slice(5, 7));
  return `FY${month >= startMonth ? year : year - 1}`;
}

// The periods on a sheet, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class PeriodsApi {
  private readonly http = inject(HttpClient);

  /** The sheet's periods by from-date. */
  list(sheet: string): Promise<PeriodView[]> {
    return firstValueFrom(this.http.get<PeriodView[]>(this.url(sheet)));
  }

  /** Add a period; refused when its dates are reversed, its name is taken, or it overlaps another. */
  add(sheet: string, form: PeriodForm): Promise<PeriodView> {
    return firstValueFrom(this.http.post<PeriodView>(this.url(sheet), form));
  }

  /**
   * Generate one period per calendar month from the from-date's month to the to-date's month, named
   * yyyy-mm; months whose name is taken or whose days overlap a period are left out. The periods made.
   * Refused when the to-date is before the from-date.
   */
  generate(sheet: string, from: string, to: string): Promise<PeriodView[]> {
    return firstValueFrom(this.http.post<PeriodView[]>(`${this.url(sheet)}/generate`, { from, to }));
  }

  /** Generate the fiscal year's twelve monthly periods as generate does; the periods made. */
  generateFiscalYear(sheet: string, year: string): Promise<PeriodView[]> {
    return firstValueFrom(this.http.post<PeriodView[]>(`${this.url(sheet)}/generate-fy`, { year }));
  }

  /** Close a period, fixing its due-total; refused when it is already closed. */
  close(sheet: string, id: number): Promise<PeriodView> {

